scenario.irule:
when CLIENT_ACCEPTED { set ::client_flow [FLOW::this]; set ::server_flow [FLOW::peer $::client_flow]; FLOW::priority clientside 2; FLOW::idle_timeout $::client_flow 42; log local0. "client=$::client_flow peer=$::server_flow" }
when SERVER_CONNECTED { FLOW::priority serverside 4; set ::related [FLOW::create_related -hairpin {
 proto 17
 clientflow -local-ip 10.0.0.10 -local-port 5000 10.0.0.11 6000 vlan-a
 serverflow 10.0.0.12 7000 vlan-b
 inherit-vs /Common/app
 }]; set ::related_peer [FLOW::peer $::related]; FLOW::idle_timeout $::related 9; FLOW::priority $::related 6; set ::before [FLOW::idle_duration $::related]; FLOW::refresh $::related; set ::after [FLOW::idle_duration $::related]; log local0. "server=[FLOW::this] priority=[FLOW::priority] related=$::related peer=$::related_peer before=$::before after=$::after" }
when HTTP_REQUEST { pool app }
